<?php

declare(strict_types=1);

namespace Wurk\Portal\Support;

use Illuminate\Database\Connection;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Hash;
use Illuminate\Support\Str;
use Wurk\Audit\Contracts\AuditLog;
use Wurk\Crm\Contracts\ContactBook;
use Wurk\Identity\Contracts\Accounts;
use Wurk\Messaging\Contracts\MessageTemplates;
use Wurk\Messaging\Contracts\Messenger;
use Wurk\Tenancy\Contracts\TenantContext;

/**
 * Default passwords for the customer portal (Sprint 13.6b; decision J). Generated by WURK, sent once (email, or SMS
 * when the owner asks), never seen by staff, single-use, valid 7 days, and swapped for the customer's own at first
 * sign-in. Kept per business — never on the WURK ID — and never issued to someone whose WURK ID has its own password.
 */
final readonly class DefaultPasswords
{
    public const DAYS = 7;

    public const TEMPLATE = [
        'group' => 'Your account', 'label' => 'Your account password', 'placeholders' => ['client', 'business', 'link', 'password', 'days'], 'required' => ['password', 'link'],
        'subject' => 'Your account with {business}',
        'text' => 'Hi {client}, you can now see your rewards, orders and bookings with {business} at {link}. Sign in with this password: {password} — it works once, for {days} days, and you’ll choose your own.',
        'sample' => ['client' => 'Thandi', 'business' => 'Glow Salon', 'link' => 'glow-salon.wurk.co.za/account', 'password' => 'K7pq-Wx3m-Rt9b', 'days' => '7'], 'channels' => ['email', 'sms'],
    ];

    public function __construct(private TenantContext $context, private ContactBook $contacts, private Accounts $accounts, private AuditLog $audit) {}

    public function allowed(): bool
    {
        return (bool) $this->db()->table('portal_settings')->where('tenant_id', $this->context->id())->value('passwords_allowed');
    }

    public function setAllowed(bool $on): void
    {
        $this->db()->table('portal_settings')->updateOrInsert(['tenant_id' => $this->context->id()], ['passwords_allowed' => $on]);
        $this->audit->record('portal.passwords', 'portal_settings', 'passwords_allowed', ['on' => $on]);
    }

    /**
     * Issue and send a default password by email or SMS. Returns why not, if it wasn't sent.
     *
     * @return 'sent'|'not_allowed'|'has_password'|'no_address'
     */
    public function issue(string $contactId, string $channel): string
    {
        if (! $this->allowed()) {
            return 'not_allowed';
        }
        $p = $this->contacts->profile($contactId);
        $to = $channel === 'sms' ? ($p['phone'] ?? null) : ($p['email'] ?? null);
        if ($to === null) {
            return 'no_address';
        }
        if ($this->accounts->hasPassword($to)) {
            return 'has_password'; // they use their own WURK ID password
        }
        $password = implode('-', str_split(Str::password(12, symbols: false), 4)); // e.g. K7pq-Wx3m-Rt9b
        $this->db()->transaction(function () use ($contactId, $to, $password): void {
            $this->db()->table('portal_default_passwords')->where('tenant_id', $this->context->id())->where('contact_id', $contactId)->whereNull('used_at')
                ->update(['used_at' => now()]); // one live default password per customer
            $this->db()->table('portal_default_passwords')->insert(['id' => (string) Str::ulid(), 'tenant_id' => $this->context->id(), 'contact_id' => $contactId,
                'destination' => mb_strtolower($to), 'hash' => Hash::make($password), 'expires_at' => now()->addDays(self::DAYS), 'created_at' => now()]);
        });
        $tenant = $this->context->current();
        $vars = ['client' => explode(' ', (string) ($p['name'] ?? 'there'))[0], 'business' => $tenant->displayName(),
            'link' => $tenant->handle().'.'.config('wurk.domains.root').'/account', 'password' => $password, 'days' => (string) self::DAYS];
        $channel === 'sms'
            ? app(Messenger::class)->sms($to, app(MessageTemplates::class)->text('portal.password', 'sms', $vars), 'portal.password')
            : app(MessageTemplates::class)->email('portal.password', $to, $vars);
        $this->audit->record('portal.password_sent', 'contact', $contactId, ['channel' => $channel]); // never the password

        return 'sent';
    }

    /** Whether this customer's valid default password matches (and uses it up) — single-use, even if two sign-ins race. */
    public function redeem(string $contactId, string $password): bool
    {
        $rows = $this->db()->table('portal_default_passwords')->where('tenant_id', $this->context->id())->where('contact_id', $contactId)
            ->whereNull('used_at')->where('expires_at', '>', now())->get();
        foreach ($rows as $r) {
            if (Hash::check($password, (string) $r->hash)) {
                return $this->db()->table('portal_default_passwords')->where('tenant_id', $this->context->id())->where('id', $r->id)->whereNull('used_at')->update(['used_at' => now()]) === 1;
            }
        }

        return false;
    }

    private function db(): Connection
    {
        return DB::connection($this->context->connectionName());
    }
}
